import{_ as o,r as a,o as r,c as l,e as t,a as p,s as i}from"./chunks/framework.CXcwiNg-.js";const w=JSON.parse('{"title":"Meet the AJAX Framework - October CMS User Guide","titleTemplate":false,"description":"A lightweight AJAX framework that replaces the need for building API endpoints","frontmatter":{"subtitle":"A lightweight AJAX framework that replaces the need for building API endpoints"},"headers":[{"level":2,"title":"How It Works","slug":"how-it-works","link":"#how-it-works","children":[]},{"level":2,"title":"Handlers Live on the Page","slug":"handlers-live-on-the-page","link":"#handlers-live-on-the-page","children":[]},{"level":2,"title":"Sending Data","slug":"sending-data","link":"#sending-data","children":[]},{"level":2,"title":"Updating the Page","slug":"updating-the-page","link":"#updating-the-page","children":[]},{"level":2,"title":"What We Already Set Up","slug":"what-we-already-set-up","link":"#what-we-already-set-up","children":[]},{"level":2,"title":"Next Steps","slug":"next-steps","link":"#next-steps","children":[]}],"relativePath":"user-guide/quickstart/interactive-features/ajax-introduction.md","filePath":"user-guide/quickstart/interactive-features/ajax-introduction.md"}'),c={name:"user-guide/quickstart/interactive-features/ajax-introduction.md"};function d(u,e,h,g,k,m){const n=a("pre-heading"),s=a("post-heading");return r(),l("div",null,[t(n),e[0]||(e[0]=p("h1",null,"Meet the AJAX Framework",-1)),t(s),e[1]||(e[1]=i(`<p>October CMS ships with a built-in AJAX framework called <strong>Larajax</strong>. Think of it as <code>fetch()</code> in JavaScript, but with extra features built in: DOM patching, form validation, flash messages, and loading indicators. It is designed to be simple enough to learn in minutes, yet powerful enough to grow with your project.</p><p>The key idea: instead of building separate API endpoints and writing JavaScript to call them, you define <strong>handlers</strong> directly on your pages. The framework connects your HTML elements to those handlers automatically. It is still an API, but it lives on the page itself, so there is no routing or controller boilerplate.</p><h2 id="how-it-works"><a href="#how-it-works" class="header-anchor">#</a> How It Works</h2><p>The framework revolves around one HTML attribute: <code>data-request</code>. Add it to almost any element (a button, a form, a link, a dropdown) and the framework will call the named handler on the server when that element is triggered.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onSayHello<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Click Me<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>When the visitor clicks this button, the framework sends an AJAX request to the server, which runs the <code>onSayHello</code> handler. No JavaScript code needed.</p><p>Different elements trigger at different moments:</p><div class="table"><table tabindex="0"><thead><tr><th>Element</th><th>Triggers When</th></tr></thead><tbody><tr><td>Form</td><td>The form is submitted</td></tr><tr><td>Button, link</td><td>The element is clicked</td></tr><tr><td>Select, checkbox, radio</td><td>The selection changes</td></tr><tr><td>Text input</td><td>The text changes (with <code>data-track-input</code>)</td></tr></tbody></table></div><h2 id="handlers-live-on-the-page"><a href="#handlers-live-on-the-page" class="header-anchor">#</a> Handlers Live on the Page</h2><p>An AJAX handler is a PHP function defined in the <strong>code section</strong> of your page file. The code section sits between <code>==</code> separators, above the Twig markup. Handler names always start with <code>on</code>.</p><p>Here is what a page with a handler looks like in the backend editor:</p><p><strong>Code</strong> tab:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onSayHello</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// This runs on the server when the button is clicked</span>
<span class="token punctuation">}</span>
</code></pre></div><p><strong>Markup</strong> tab:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onSayHello<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Click Me<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>That is the entire pattern. The HTML triggers the handler, the handler runs PHP on the server, and the framework takes care of the request/response cycle.</p><h2 id="sending-data"><a href="#sending-data" class="header-anchor">#</a> Sending Data</h2><p>When <code>data-request</code> is used inside a form, all form input values are sent to the server automatically. You can read them with the <code>input()</code> helper:</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onSayHello</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$name</span> <span class="token operator">=</span> <span class="token function">input</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>You can also send data from individual elements using <code>data-request-data</code>:</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onLoadPage<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-request-data</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>page: 2<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Next Page
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="updating-the-page"><a href="#updating-the-page" class="header-anchor">#</a> Updating the Page</h2><p>The framework can update parts of the page after a request completes. There are two directions:</p><ul><li><strong>Pull</strong>: the browser requests a partial to be rendered and tells the framework where to put it.</li><li><strong>Push</strong>: the handler decides what to update and sends the HTML back.</li></ul><p>We will explore both approaches in detail in <a href="./flash-messages-and-loaders.html">Updating the Page</a>. For now, just know that the framework can surgically patch the DOM without reloading the entire page.</p><h2 id="what-we-already-set-up"><a href="#what-we-already-set-up" class="header-anchor">#</a> What We Already Set Up</h2><p>If you have been following along, your layout already includes this line:</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">framework</span> extras <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>This loads the AJAX framework with its <strong>extras</strong>: automatic validation error display, flash message notifications, and a loading progress bar. We added this when we <a href="./../editor/creating-a-layout.html">created the layout</a>, so there is nothing else to set up.</p><h2 id="next-steps"><a href="#next-steps" class="header-anchor">#</a> Next Steps</h2><p>Now that you understand the basics, let&#39;s put the framework to work. Continue to <a href="./building-forms.html">Build a Form</a> to add a contact form to the team profile page.</p><p>For the complete AJAX framework reference, see <a href="./../../../4.x/cms/ajax/introduction.html">AJAX Introduction</a> in the developer documentation.</p>`,32))])}const v=o(c,[["render",d]]);export{w as __pageData,v as default};
